 "content": "def transform(grid):
    """Copy the linear color motif, centered on each isolated marker."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest straight contiguous run that is not background.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if c - start >= 2:
                runs.append((c - start, [(r, x) for x in range(start, c)], (0, 1)))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            if r - start >= 2:
                runs.append((r - start, [(x, c) for x in range(start, r)], (1, 0)))
    if not runs:
        return [row[:] for row in grid]
    _, motif_coords, direction = max(runs, key=lambda item: item[0])
    motif = [grid[r][c] for r, c in motif_coords]
    motif_colors = set(motif)
    motif_set = set(motif_coords)

    # The marker is a non-background color absent from the motif.
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in motif_colors
               and (r, c) not in motif_set]
    out = [row[:] for row in grid]
    dr, dc = direction
    center = len(motif) // 2
    for r, c in markers:
        for i, color in enumerate(motif):
            rr = r + (i - center) * dr
            cc = c + (i - center) * dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
