    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    # Find the reference 3-cell line. Its center cell marks the target color
    # in demonstrations; it is the non-background color absent from motif.
    runs=[]
    for r in range(h):
        for c in range(w-2):
            if all(grid[r][c+i]!=bg for i in range(3)):
                runs.append(([(r,c+i) for i in range(3)],(0,1)))
    for c in range(w):
        for r in range(h-2):
            if all(grid[r+i][c]!=bg for i in range(3)):
                runs.append(([(r+i,c) for i in range(3)],(1,0)))
    # Choose rarest isolated 3-run: reference line is typically placed at edge.
    coords,direction=max(runs,key=lambda x: (sum(grid[r][c]!=bg for r,c in x[0]), -sum(1 for r,c in x[0] if grid[r][c]==bg)))
    colors=[grid[r][c] for r,c in coords]
    palette=set(colors)
    # Target is the color with most occurrences outside reference motif.
    counts=Counter(x for row in grid for x in row if x!=bg and x not in palette)
    marker=max(counts,key=counts.get)
    out=[row[:] for row in grid]
    dr,dc=direction
    for r in range(h):
        for c in range(w):
            if grid[r][c]==marker:
                for i,v in enumerate(colors):
                    rr=r+(i-1)*dr; cc=c+(i-1)*dc
                    if 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    return out
